import{t as e}from"./jsx-runtime-CY_jTiqj.js";import{r as t}from"./ThemeToggle-2sZo9z4q.js";import{t as n}from"./boxes-2eECxXB0.js";import{A as r,C as i,E as a,M as o,N as s,O as c,P as l,T as u,k as d,l as f,n as p,o as m,p as h,t as g,v as _}from"./shared-JA1PGxXr.js";import{t as v}from"./database-B3KIbapA.js";import{t as y}from"./CodeEditor-DqHMt3P8.js";var b=t(`Table2`,[[`path`,{d:`M9 3H5a2 2 0 0 0-2 2v4m6-6h10a2 2 0 0 1 2 2v4M9 3v18m0 0h10a2 2 0 0 0 2-2V9M9 21H5a2 2 0 0 1-2-2V9m0 0h18`,key:`gugj83`}]]),x=e(),S=`Этап 4 · Блок 14 · Подготовка базы и новой границы хранения`;function C({module:e}){return(0,x.jsxs)(s,{children:[(0,x.jsx)(o,{variant:`project`,chip:e??S,title:`Модель ORM и таблица`,intro:`Опишем отдельную ORM-строку и создадим исходную таблицу, пока рабочий Planner продолжает использовать JSON.`,tags:[{icon:(0,x.jsx)(n,{size:14}),label:`три представления задачи`},{icon:(0,x.jsx)(b,{size:14}),label:`исходная схема`},{icon:(0,x.jsx)(v,{size:14}),label:`явное создание`}]}),(0,x.jsxs)(l,{number:`00`,title:`От настроенного подключения к описанию таблицы`,children:[(0,x.jsx)(c,{children:`В Planner уже есть предметная Task с правилами, HTTP-схема ответа и сохранение после перезапуска через JSON. Предыдущие шаги должны были дать SQLite и настроенный Engine. Теперь отделим описание будущей таблицы от привычных объектов приложения.`}),(0,x.jsx)(d,{variant:`connected`,items:[{title:`Точка старта`,description:`Предметная Task, HTTP-ответ и JSON-хранение уже существуют. API и CLI пока продолжают работать с JSON.`},{title:`Новый вопрос`,description:`Как описать поля Planner в таблице так, чтобы не смешать предметную модель, ORM-строку и HTTP-схему?`},{title:`Результат`,description:`Мы подготовим TaskRow, зарегистрируем исходную таблицу и создадим схему отдельной командой.`}]}),(0,x.jsx)(`p`,{children:`Сначала разберём роли трёх представлений и способ связать ORM-класс с метаданными. Затем зададим колонки и ограничения, отдельно рассмотрим tags и служебный поисковый текст. В конце пройдём явное создание таблицы и проверим, что оно не меняет уже существующую схему.`}),(0,x.jsx)(a,{children:`Практика предполагает, что мы уже прошли SQL и Engine в шагах 66–67. Журнал StudyHub сейчас подтверждает обучение только до 65.2. Если предыдущие шаги ещё не выполнены, сначала восстановим их результат и проверим подключение, затем вернёмся к проектной части.`})]}),(0,x.jsxs)(l,{number:`01`,title:`Task, TaskRow и TaskRead решают разные задачи`,children:[(0,x.jsx)(c,{children:`Одно слово «задача» скрывает несколько ролей. Мы не будем превращать новую таблицу в повод переписать уже работающий Planner.`}),(0,x.jsx)(`p`,{children:`Предметная Task уже хранит id, title, priority, is_done и tags, проверяет значения и поддерживает правила приложения. HTTP-схема TaskRead описывает, что API отдаёт клиенту. ORM-класс TaskRow будет описывать строку таблицы и связь её полей с колонками. Он не заменит Task и сам по себе не меняет ответ API.`}),(0,x.jsx)(r,{rows:[[(0,x.jsx)(`code`,{children:`Task`}),`Предметные данные и правила Planner`],[(0,x.jsx)(`code`,{children:`TaskRow`}),`ORM-представление одной строки таблицы`],[(0,x.jsx)(`code`,{children:`TaskRead`}),`Публичная форма HTTP-ответа`],[(0,x.jsx)(`code`,{children:`JsonStorage`}),`Текущий путь сохранения всего списка задач`]]}),(0,x.jsx)(`p`,{children:`Представим заказ в сервисе доставки. Карточка заказа хранит смысл и правила, строка складской системы фиксирует данные в таблице, а короткая квитанция показывает клиенту разрешённые сведения. Эти формы могут описывать один заказ, но у каждой свой договор. Аналогия заканчивается там, где ORM дополнительно связывает Python-атрибуты с реальными колонками.`}),(0,x.jsx)(`p`,{children:`В нашей таблице сохранятся внутренние tags, хотя HTTP-ответ пока не выдаёт их наружу. Поле title_normalized тоже будет техническим: оно понадобится для сохранения прежнего поиска, но не станет новым свойством задачи для клиента. Это занятие создаёт описание таблицы, а преобразование TaskRow обратно в Task появится позже.`}),(0,x.jsx)(u,{question:`Для отдельного каталога закладок какой вариант сохраняет разные роли предметного объекта и строки таблицы?`,left:{title:`Один mapped-класс`,code:`class Bookmark(Base):
    __tablename__ = 'bookmarks'
    label: Mapped[str] = mapped_column(String)`,note:`Сам класс сразу становится ORM-строкой.`},right:{title:`Два явных представления`,code:`@dataclass
class Bookmark:
    label: str

class BookmarkRow(Base):
    __tablename__ = 'bookmarks'
    label: Mapped[str] = mapped_column(String)`,note:`Предметный объект и строка имеют отдельные роли.`},preferred:`right`,explanation:`Для этого Planner выбираем два представления: Task уже несёт предметные правила, а TaskRow добавляется для базы. Один mapped-класс возможен в других архитектурах, но здесь он изменил бы границы существующей модели.`})]}),(0,x.jsxs)(l,{number:`02`,title:`DeclarativeBase связывает класс с таблицей`,children:[(0,x.jsx)(c,{children:`В SQLAlchemy 2 описание ORM начинается с декларативной базы. Её наследник задаёт имя таблицы и атрибуты, которые библиотека соберёт в схему.`}),(0,x.jsx)(`p`,{children:`Базовый класс наследуется от DeclarativeBase. Когда мы определяем BookmarkRow или будущий TaskRow как его подкласс, SQLAlchemy строит сопоставление класса с таблицей и добавляет описание таблицы в Base.metadata. Имя таблицы задаёт __tablename__. Атрибут с Mapped[str] обозначает типизированное поле ORM, а mapped_column сообщает настройки колонки, например её SQL-тип, ключ и nullable.`}),(0,x.jsx)(y,{caption:`Независимый пример с закладкой`,code:`from sqlalchemy import Integer, String
from sqlalchemy.orm import DeclarativeBase, Mapped, mapped_column

class BookmarkBase(DeclarativeBase):
    pass

class BookmarkRow(BookmarkBase):
    __tablename__ = 'bookmarks'

    id: Mapped[int] = mapped_column(Integer, primary_key=True)
    label: Mapped[str] = mapped_column(String, nullable=False)`}),(0,x.jsx)(`p`,{children:`Этот пример только описывает связь. При выполнении определения класса появляется объект схемы в metadata, но SQL к базе ещё не отправлен. Вызов Base.metadata.create_all(engine) будет отдельным действием. Поэтому импорт файла модели может зарегистрировать таблицу, но не создаёт её в SQLite.`}),(0,x.jsx)(`p`,{children:`Представим картотеку чертежей мастерской. Определение mapped-класса добавляет чертёж в каталог, а metadata хранит весь каталог для одной базы. Пока мастер не получил явную команду и адрес мастерской, новая полка не появляется. В реальном коде metadata не физическая коробка, а Python-описание, которое SQLAlchemy использует при работе с Engine.`}),(0,x.jsx)(h,{prompt:`Свяжем каждый элемент ORM-описания с его ролью`,leftTitle:`Элемент`,rightTitle:`Назначение`,pairs:[{left:(0,x.jsx)(`code`,{children:`DeclarativeBase`}),right:`Базовый класс и общая metadata`},{left:(0,x.jsx)(`code`,{children:`Mapped[int]`}),right:`Типизированный ORM-атрибут`},{left:(0,x.jsx)(`code`,{children:`mapped_column`}),right:`Настройки конкретной колонки`},{left:(0,x.jsx)(`code`,{children:`__tablename__`}),right:`Имя таблицы в базе`}],explanation:`Класс связывает Python-имена с таблицей, а metadata собирает описание зарегистрированных таблиц.`}),(0,x.jsx)(`p`,{children:`Типовая аннотация помогает описать ожидаемое значение ORM-атрибута. Она не запускает валидаторы Task для произвольных данных и не означает, что таблица уже существует. На следующем шаге мы зададим базовые поля с учётом обеих границ: правила модели остаются в Planner, а ограничения базы защищают таблицу.`})]}),(0,x.jsxs)(l,{number:`03`,title:`Колонки сохраняют договор данных`,children:[(0,x.jsx)(c,{children:`Исходная таблица должна сразу вместить прежние данные и нужную будущим операциям служебную копию заголовка. Мы не добавляем новые свойства продукта.`}),(0,x.jsx)(`p`,{children:`Primary key помечает колонку, которая однозначно называет строку. Для id выбираем целое значение и сохраняем положительный диапазон. title остаётся обязательным текстом без нового предела длины: HTTP-ограничение уже есть для запросов, но старые CLI-данные могли быть длиннее. Поэтому не задаём для колонки произвольные 120 символов.`}),(0,x.jsx)(r,{rows:[[(0,x.jsx)(`code`,{children:`id`}),`Integer primary key и проверка id больше нуля`],[(0,x.jsx)(`code`,{children:`title`}),`Обязательный текст без нового максимума длины`],[(0,x.jsx)(`code`,{children:`priority`}),`Целое число от 1 до 5, прежний default равен 2`],[(0,x.jsx)(`code`,{children:`is_done`}),`Boolean, обязательное поле с начальным значением False`],[(0,x.jsx)(`code`,{children:`tags`}),`JSON-список строк из предметной модели`],[(0,x.jsx)(`code`,{children:`title_normalized`}),`Технический текст для прежнего поиска`]]}),(0,x.jsx)(`p`,{children:`nullable=False запрещает оставить колонку пустой в строке базы. CheckConstraint задаёт проверку на уровне таблицы, например id больше нуля или priority между 1 и 5. Это дополнительная ограда для данных, дошедших до базы через разные пути. Она не заменяет проверку Task: приложение по-прежнему должно сообщать пользователю понятную ошибку до сохранения.`}),(0,x.jsx)(`p`,{children:`Для is_done мы выберем SQLAlchemy Boolean и default=False. SQLite хранит логические значения в числовом виде, обычно как 0 и 1. Тип колонки помогает SQLAlchemy переводить эти значения, а Python-модель продолжает проверять bool. Если прямой SQL должен полностью повторять предметное ограничение, его нужно выразить отдельной проверкой, а не полагаться только на название типа.`}),(0,x.jsx)(`p`,{children:`Default в mapped_column обычно задаёт значение, которое SQLAlchemy применит при INSERT, если поле не передано. Это не обязательно означает, что сразу после вызова конструктора Python уже увидит такое значение на объекте. На этом шаге мы не создаём строку и не изучаем Session: мы проверяем описание, которое пригодится при первой записи позднее.`}),(0,x.jsx)(`p`,{children:`Сверим несколько решений по их назначению. Так легче заметить, где сработает доменная проверка, а где ограничение таблицы.`}),(0,x.jsx)(h,{prompt:`Найдём границу действия каждого механизма`,leftTitle:`Механизм`,rightTitle:`Что он защищает`,pairs:[{left:(0,x.jsx)(`code`,{children:`Task.__post_init__`}),right:`Предметные правила в Python-приложении`},{left:(0,x.jsx)(`code`,{children:`nullable=False`}),right:`Наличие значения в строке таблицы`},{left:(0,x.jsx)(`code`,{children:`CheckConstraint`}),right:`Условие для всех записей таблицы`},{left:(0,x.jsx)(`code`,{children:`default=False`}),right:`Значение ORM при будущей вставке`}],explanation:`Ограничения таблицы дополняют проверку Task. Настройка default не заменяет ни одну из этих проверок.`})]}),(0,x.jsxs)(l,{number:`04`,title:`JSON tags и служебная копия заголовка`,children:[(0,x.jsx)(c,{children:`Две колонки нужны не для новых пользовательских функций. Они сохраняют уже сложившееся устройство Planner и его будущую семантику поиска.`}),(0,x.jsx)(`p`,{children:`tags остаётся списком строк внутри одной задачи. Для этой исходной схемы подходит SQLAlchemy JSON: SQLite хранит сериализуемое JSON-значение в колонке, поэтому отдельная таблица тегов здесь не нужна. JSON-тип сам по себе не гарантирует список строк и не запускает validate_tags. Эти правила остаются у Task.`}),(0,x.jsx)(`p`,{children:`Для default указываем функцию list, чтобы будущая вставка получила новый пустой список. Это похоже на форму для выпечки: каждый новый заказ получает отдельную заготовку. Если передать один изменяемый список как постоянное значение, независимость записей нельзя считать гарантированной. При этом ORM не замечает каждое изменение внутри уже присвоенного JSON-списка на месте без дополнительного механизма. Такой механизм мы сейчас не добавляем.`}),(0,x.jsx)(`p`,{children:`title_normalized хранит title.lower() по уже знакомому Python правилу. Поиск курса учитывает русские заголовки, а встроенные SQLite lower и LIKE не обязаны давать тот же результат. Поэтому отдельный текст запланирован заранее, не объявляется уникальным и не показывается в HTTP. Все будущие пути создания или переименования будут записывать его рядом с title. Здесь таблица пока пуста, и мы только закладываем необходимую колонку.`}),(0,x.jsx)(i,{code:`class LabelRow(Base):
    __tablename__ = 'labels'
    tags: Mapped[list[str]] = mapped_column(JSON, nullable=False, default=[])`,question:`Что мешает этому default выразить отдельный пустой список для каждой будущей строки?`,options:[`Список передан готовым изменяемым значением, а не функцией создания`,`JSON в SQLite может содержать только словари`,`mapped_column не принимает тип JSON`],correctIndex:0,explanation:`Для значения на каждой вставке передаём list как callable. Он создаёт новый объект списка; единый литерал [] сам по себе этого не обещает.`,fix:`tags: Mapped[list[str]] = mapped_column(JSON, nullable=False, default=list)`})]}),(0,x.jsxs)(l,{number:`05`,title:`Модель регистрируется до явного создания схемы`,children:[(0,x.jsx)(c,{children:`Описание таблицы и её физическое создание происходят в разных местах и в разное время. Это разделение защищает обычный запуск приложения от неожиданных изменений базы.`}),(0,x.jsx)(`p`,{children:`В init_db.py сначала импортируется модуль с ORM-классами. Когда Python выполняет определения Base и TaskRow, таблица попадает в Base.metadata. Затем отдельная функция получает Engine из настроек предыдущего шага и вызывает create_all. Важно импортировать модели до этой команды: пустая metadata не сможет создать таблицу, о которой Python ещё не знает.`}),(0,x.jsx)(`p`,{children:`Команда создания запускается только явно, например как отдельный модуль проекта. Код внутри неё следует отделить функцией и защитить условием запуска файла. Тогда импорт api.py или engine.py не создаёт таблицы. Engine даёт доступ к базе, но создание схемы остаётся отдельным административным действием.`}),(0,x.jsx)(`p`,{children:`На схеме стрелки показывают порядок: импорт выполняет описание модели, описание пополняет metadata, явный create_all использует Engine и создаёт отсутствующую таблицу. Сам импорт не отправляет DDL, а вызов create_all не вставляет задачу.`}),(0,x.jsx)(g,{caption:`Путь от определения ORM-класса к отсутствующей таблице`,orientation:`horizontal`,children:(0,x.jsxs)(m,{label:`Регистрация и создание исходной таблицы`,orientation:`horizontal`,children:[(0,x.jsx)(f,{title:`models.py`,shape:`process`,children:(0,x.jsx)(`p`,{children:`Определяем Base и TaskRow`})}),(0,x.jsx)(p,{label:`импорт выполняет класс`}),(0,x.jsx)(f,{title:`Base.metadata`,shape:`process`,children:(0,x.jsx)(`p`,{children:`Хранит описание tasks в Python`})}),(0,x.jsx)(p,{label:`явный вызов`}),(0,x.jsx)(f,{title:`create_all(engine)`,shape:`process`,children:(0,x.jsx)(`p`,{children:`Создаёт отсутствующие таблицы`})}),(0,x.jsx)(p,{label:`DDL для схемы`}),(0,x.jsx)(f,{title:`SQLite: tasks`,shape:`database`,children:(0,x.jsx)(`p`,{children:`Физическая таблица без записей`})})]})}),(0,x.jsx)(`p`,{children:`Читаем схему слева направо. Первый переход происходит в памяти Python, последний требует явной команды и подходящего Engine. Если переставить эти роли, можно получить пустую metadata или случайное создание таблицы при импорте приложения.`}),(0,x.jsx)(_,{code:`import app.DBase.models
from app.DBase.models import Base
Base.metadata.create_all(engine)`,steps:[{line:0,note:`Импорт запускает определения модели. TaskRow регистрирует таблицу в metadata, но SQLite не меняется.`},{line:1,note:`Мы получаем общий объект metadata, в котором теперь описана таблица tasks.`},{line:2,note:`Только этот явный вызов обращается к Engine и создаёт отсутствующую схему.`}]})]}),(0,x.jsxs)(l,{number:`06`,title:`create_all создаёт недостающее, но не исправляет старое`,children:[(0,x.jsx)(c,{children:`Явная команда должна быть безопасна при повторном запуске, но у неё узкая роль. Мы заранее проверим, что именно позволяет узнать SQLite.`}),(0,x.jsx)(`p`,{children:`PRAGMA table_info(tasks) перечисляет текущие колонки таблицы, их типы, nullable, значения по умолчанию и отметку primary key. Запрос к sqlite_master помогает прочитать сохранённое определение таблицы и увидеть текст ограничений. Это диагностические запросы: они не изменяют схему и не доказывают поведение будущего ORM-сохранения.`}),(0,x.jsx)(y,{caption:`Диагностика только для изолированной SQLite-базы`,code:`from sqlalchemy import text

with engine.connect() as connection:
    columns = connection.execute(text('PRAGMA table_info(tasks)')).all()
    create_sql = connection.execute(
        text('SELECT sql FROM sqlite_master WHERE type = :kind AND name = :name'),
        {'kind': 'table', 'name': 'tasks'},
    ).scalar_one()`}),(0,x.jsx)(`p`,{children:`create_all по умолчанию проверяет существование каждой таблицы и создаёт только отсутствующие. Если таблица tasks уже есть, но в ней не хватает колонки, эта команда не превратится в миграцию и не починит различие. Сначала сравниваем реальное описание с metadata. Несовпадающую схему исследуем только на отдельном временном файле, чтобы не затронуть данные пользователя.`}),(0,x.jsx)(`p`,{children:`Повторный запуск на совпадающей исходной схеме не создаёт вторую таблицу и не удаляет строки. Из этого не следует, что можно безопасно запускать любую экспериментальную модель на рабочей базе. Поэтому в этом занятии мы создаём пустую исходную таблицу из настроек теста, повторяем явную команду и отдельно проверяем, что простой импорт её не создаёт.`}),(0,x.jsx)(`p`,{children:`Осторожность здесь похожа на сверку чертежа перед строительством. Команда проверяет наличие объекта, но не перепланирует уже построенное помещение. В нашем случае проверка наличия экономит повторный CREATE, а несовпадающие колонки требуют отдельного решения в будущей главе. Здесь нет Alembic, изменения существующей схемы или автоматического переключения Planner на SQLite.`})]}),(0,x.jsxs)(l,{number:`07`,title:`Что мы будем делать в практике`,children:[(0,x.jsx)(`p`,{children:`Подготовим исходную ORM-схему для существующего StudyHub Planner на отдельной SQLite-базе. Рабочие API, CLI и JSON продолжат использовать прежний путь.`}),(0,x.jsx)(d,{variant:`connected`,items:[{title:`Опишем TaskRow`,description:`Получим отдельный ORM-класс и metadata с шестью согласованными колонками.`},{title:`Создадим схему явно`,description:`Получим команду init_db.py, запускаемую с Engine и настройками из предыдущего шага.`},{title:`Проверим договор таблицы`,description:`Получим список колонок, primary key, обязательность значений и заданные ограничения.`},{title:`Повторим создание и импорт`,description:`Получим тот же состав таблиц после повторного запуска и отсутствие DDL при обычном импорте.`}]}),(0,x.jsx)(`p`,{children:`Каждое действие опирается на разделение Task и TaskRow, описание metadata и границу create_all. Практика не добавляет ORM-запись, Session, CRUD или новую пользовательскую возможность.`}),(0,x.jsx)(`p`,{children:`Сначала подтвердим, что действительно готовы Engine и SQL из занятий 66–67. Затем используем только отдельный тестовый URL и сохраним прежний JSON Planner. На выходе будет исходная таблица, к которой следующее занятие сможет добавить первую ORM-запись.`})]})]})}export{C as Lesson67_1};